  tu.name = 'tooth';
  teethUpper.add(tu);
  upperTeeth.push(tu);
  const tl = new THREE.Mesh(boxGeo, toothMat);
  tl.name = 'tooth';
  teethLower.add(tl);
  lowerTeeth.push(tl);
